import {act,fireEvent,render,screen} from "@testing-library/react";import {renderToStaticMarkup} from "react-dom/server";import {expect,test,vi} from "vitest";import {TicketMeta,ListMeta} from "./TicketMeta";import {EditorStyles,OverviewHint,TicketLink,warmTicket} from "./resources";import {metadata,safeThumbnail} from "./metadataModel";import {sample} from "./metadataLab";
test("metadane szczegółów trafiają do head i znikają przy przejściu na listę",async()=>{const view=render(<TicketMeta ticket={sample}/>);expect(document.title).toBe("#42 API timeout · DevDesk");expect(document.head.querySelectorAll("title")).toHaveLength(1);expect(document.body.querySelector("title")).toBeNull();expect(document.head.querySelector('meta[name="description"]')).toHaveAttribute("content","Publiczny opis");expect(document.head.querySelector('link[rel="canonical"]')).toHaveAttribute("href","https://devdesk.example/tickets/42");await act(async()=>view.rerender(<ListMeta openCount={3}/>));expect(document.title).toBe("Tickety (3 otwartych) · DevDesk");expect(document.head.querySelectorAll("title")).toHaveLength(1);expect(document.head.querySelector('meta[name="description"]')).toBeNull();expect(document.head.querySelector('link[rel="canonical"]')).toBeNull();});
test("unmount usuwa metadane ekranu",()=>{const view=render(<TicketMeta ticket={sample}/>);view.unmount();expect(document.head.querySelector("title")).toBeNull();expect(document.head.querySelector('meta[property="og:title"]')).toBeNull();});
test("prywatny ticket nie ujawnia treści w metadanych",()=>{render(<TicketMeta ticket={{...sample,visibility:"private",title:"TAJNY",description:"SEKRET"}}/>);expect(document.head.innerHTML).not.toContain("TAJNY");expect(document.head.innerHTML).not.toContain("SEKRET");expect(document.head.querySelector('meta[name="robots"]')).toHaveAttribute("content","noindex,nofollow");});
test("render serwerowy emituje metadane w dokumencie",()=>{const html=renderToStaticMarkup(<html><head/><body><TicketMeta ticket={sample}/><h1>Ticket</h1></body></html>),parsed=new DOMParser().parseFromString(html,"text/html");expect(parsed.head.querySelector("title")?.textContent).toBe(metadata(sample).title);expect(parsed.head.querySelector('meta[property="og:url"]')?.getAttribute("content")).toBe(metadata(sample).url);expect(parsed.body.querySelector("title")).toBeNull();});
test("tekst metadanych nie staje się wykonywalnym HTML",()=>{const html=renderToStaticMarkup(<html><head/><body><TicketMeta ticket={{...sample,title:'<script>alert(1)</script>',description:'\"/><script>alert(2)</script>'}}/></body></html>),parsed=new DOMParser().parseFromString(html,"text/html");expect(parsed.querySelector("script")).toBeNull();expect(parsed.title).toContain("<script>");expect(parsed.head.querySelector('meta[name="description"]')?.getAttribute("content")).toBe('\"/><script>alert(2)</script>');});
test("focus i hover deklarują wskazówki tylko dla zaufanej miniatury",()=>{const hints={connect:vi.fn(),image:vi.fn()},ticket={...sample,thumbnailUrl:"https://files.devdesk.example/thumbs/42.webp"};render(<TicketLink ticket={ticket} hints={hints}/>);fireEvent.focus(screen.getByRole("link"));fireEvent.mouseEnter(screen.getByRole("link"));expect(hints.connect).toHaveBeenCalledWith("https://files.devdesk.example");expect(hints.image).toHaveBeenCalledWith(ticket.thumbnailUrl);expect(hints.image).toHaveBeenCalledTimes(2);expect(screen.getByRole("link")).toHaveAttribute("href","/tickets/42");});
test("prywatna lub obca miniatura nie uruchamia hints",()=>{const hints={connect:vi.fn(),image:vi.fn()};warmTicket({...sample,visibility:"private",thumbnailUrl:"https://files.devdesk.example/thumbs/42.webp"},hints);warmTicket({...sample,thumbnailUrl:"https://evil.example/thumbs/42.webp"},hints);warmTicket(sample,hints);expect(hints.connect).not.toHaveBeenCalled();expect(hints.image).not.toHaveBeenCalled();expect(safeThumbnail("https://files.devdesk.example/thumbs/42.webp?token=sekret")).toBeNull();});
test("React deduplikuje prawdziwe wskazówki preload",()=>{render(<><OverviewHint/><OverviewHint/></>);expect(document.head.querySelectorAll('link[rel="preload"][href="/assets/board.svg"]')).toHaveLength(1);expect(document.head.querySelector('link[rel="preload"][href="/assets/board.svg"]')).toHaveAttribute("as","image");});
test("arkusz o tym samym href jest deduplikowany i ma grupę precedence",async()=>{const view=render(<><EditorStyles href="/qa-editor.css"/><EditorStyles href="/qa-editor.css"/></>);const sheets=document.head.querySelectorAll('link[rel="stylesheet"][href="/qa-editor.css"]');expect(sheets).toHaveLength(1);expect(sheets[0]).toHaveAttribute("data-precedence","editor");await act(async()=>fireEvent.load(sheets[0]));view.unmount();expect(document.head.querySelector('link[href="/qa-editor.css"]')).not.toBeNull();});

